Path('/kaggle/working/rascar_v14_full_pool.py').write_text("from pathlib import Path\nexec(Path('/kaggle/working/rascar_local_data.py').read_text())\n\nfrom pathlib import Path\nimport os,sys,json,hashlib,time\nos.environ['DISABLE_KAGGLE_CACHE']='true';os.environ['OMP_NUM_THREADS']='2'\nimport numpy as np,pandas as pd,kagglehub,torch,cv2\nfrom PIL import Image,ImageDraw\nfrom concurrent.futures import ThreadPoolExecutor\nfrom ultralytics import YOLO\nfrom scipy.special import expit\nE=Path('/kaggle/working/rascar_v14');O=Path('/kaggle/working/oof_validation_v11');Y=E/'yolo26_clean';S=E/'stage2';P=E/'stage6/pool';P.mkdir(parents=True,exist_ok=True)\nB=['x1','y1','x2','y2'];days=['2026-10-25','2026-10-26'];torch.set_num_threads(2)\nq=pd.read_csv(O/'train.csv');fr=pd.read_csv(O/'train_frames.csv');fr['day']=pd.to_datetime(fr.timestamp,utc=True,format='mixed').dt.strftime('%Y-%m-%d');q=q.merge(fr[['frame_id','day']],on='frame_id');q=q[q.class_name.isin(['person','cup','nude_hands','tray'])].reset_index(drop=True)\ndef overlap(a,b):\n a=np.asarray(a).reshape(-1,4);b=np.asarray(b).reshape(-1,4);inter=np.prod(np.maximum(0,np.minimum(a[:,None,2:],b[None,:,2:])-np.maximum(a[:,None,:2],b[None,:,:2])),axis=2);return inter/np.maximum(np.prod(a[:,2:]-a[:,:2],axis=1)[:,None]+np.prod(b[:,2:]-b[:,:2],axis=1)[None]-inter,1e-9)\n# Select a time-diverse machine sample before looking at scores.\nmf=pd.read_csv(S/'machine_frames.csv');mp=pd.read_csv(S/'machine_predictions.csv');mf['timestamp']=pd.to_datetime(mf.timestamp,utc=True,format='mixed');mf['day']=mf.timestamp.dt.strftime('%Y-%m-%d');mf['hour']=mf.timestamp.dt.floor('h')\nassert set(mf.day).issubset(set(days))\ntrain_times=pd.to_datetime(fr.timestamp,utc=True,format='mixed').astype('int64').to_numpy();mt=mf.timestamp.astype('int64').to_numpy();nearest=np.min(abs(mt[:,None]-train_times[None,:]),axis=1)/1e9\nmf=mf[nearest>600].copy();sample=pd.concat([g.sample(min(8,len(g)),random_state=17) for _,g in mf.groupby('hour')],ignore_index=True);sample.to_csv(P/'sample_frames.csv',index=False)\nprint('POOL_SCHEMA',mp.columns.tolist(),mp.head(1).to_dict('records'),'sample',len(sample),flush=True)\nimgdir=P/'images';imgdir.mkdir(exist_ok=True)\nfull=Path(kagglehub.competition_download('rascar-hack-case-1',output_dir=str(E/'full_competition')))\nprint('FULL_COMPETITION_LOCATION',str(full),flush=True)\nlookup={p.name:p for p in full.rglob('*.jpg')};print('FULL_IMAGE_FILES',len(lookup),flush=True)\n\ndownload_errors=[]\ndef fetch(row):\n try:\n  path=lookup.get(Path(row.image_path).name)\n  if path is None:raise FileNotFoundError(row.image_path)\n  return str(path)\n except Exception as e:download_errors.append({'frame_id':row.frame_id,'image_path':row.image_path,'error_type':type(e).__name__});return None\nwith ThreadPoolExecutor(max_workers=6) as pool:paths=list(pool.map(fetch,sample.itertuples(index=False)))\nsample['local_path']=paths;(P/'unavailable_images.json').write_text(json.dumps(download_errors,indent=2));sample=sample[sample.local_path.notna()].copy();sample.to_csv(P/'sample_frames.csv',index=False);print('AVAILABLE_POOL_FRAMES',len(sample),'unavailable',len(download_errors),flush=True)\nledger=[];allpred=[];review=[];seen=set();number=0\nfor fit in days:\n model=YOLO(str(Y/f'fit_{fit}/train/weights/last.pt'));part=sample[sample.day.eq(fit)]\n if part.empty:continue\n for result in model.predict(part.local_path.tolist(),imgsz=1280,device=1,conf=.05,iou=.7,max_det=300,stream=True,verbose=False):\n  fid=Path(result.path).stem;im=Image.open(result.path).convert('RGB');native=np.asarray(im);gray=cv2.cvtColor(native,cv2.COLOR_RGB2GRAY);sharp=float(cv2.Laplacian(gray,cv2.CV_64F).var());mean=float(gray.mean());sha=hashlib.sha256(Path(result.path).read_bytes()).hexdigest();quality=sharp>=20 and 25<=mean<=235 and sha not in seen;seen.add(sha)\n  ledger.append(dict(frame_id=fid,day=fit,width=im.width,height=im.height,sharpness=sharp,brightness=mean,sha256=sha,quality_ok=quality))\n  scale=np.array([1280/im.width,720/im.height]*2);rb=result.boxes.xyxy.cpu().numpy()*scale;conf=result.boxes.conf.cpu().numpy();classes=[model.names[int(c)] for c in result.boxes.cls.cpu().numpy()]\n  for j,b in enumerate(rb):allpred.append(dict(frame_id=fid,fit_day=fit,class_name=classes[j],confidence=float(conf[j]),**dict(zip(B,b))))\n  # Only cup/tray crops are proposed for a specialist detector. Person/hands are not pseudo-labeled.\n  if not quality:continue\n  source=mp[(mp.frame_id==fid)&mp.class_name.isin(['cup','tray'])&mp.confidence.ge(.7)]\n  for _,r in source.iterrows():\n   b=r[B].to_numpy(float);m=np.array([c==r.class_name for c in classes],dtype=bool)&(conf>=.65)\n   if not m.any() or min(b[2:]-b[:2])<24:continue\n   candidate_boxes=rb[m];ovs=overlap(b,candidate_boxes)[0];j=int(np.argmax(ovs))\n   if ovs[j]<.75:continue\n   # Query and independently trained teacher must closely agree on all edges.\n   t=candidate_boxes[j];bb=(b+t)/2;wh=bb[2:]-bb[:2];center=(bb[2:]+bb[:2])/2;roi=np.r_[center-np.maximum(wh*1.8,80)/2,center+np.maximum(wh*1.8,80)/2];roi[[0,2]]=np.clip(roi[[0,2]],0,1280);roi[[1,3]]=np.clip(roi[[1,3]],0,720)\n   # Reject regions containing additional cup/tray proposals: review must verify completeness.\n   others=mp[(mp.frame_id==fid)&mp.class_name.isin(['cup','tray'])]\n   other_boxes=others[B].to_numpy();inter=np.prod(np.maximum(0,np.minimum(other_boxes[:,2:],roi[2:])-np.maximum(other_boxes[:,:2],roi[:2])),axis=1)\n   if ((inter>0)&(overlap(bb,other_boxes)[0]<.5)).any():continue\n   teacher_other=np.array([c in ['cup','tray'] for c in classes],dtype=bool)&(conf>=.1);obs=rb[teacher_other]\n   if len(obs):\n    inter2=np.prod(np.maximum(0,np.minimum(obs[:,2:],roi[2:])-np.maximum(obs[:,:2],roi[:2])),axis=1)\n    if ((inter2>0)&(overlap(bb,obs)[0]<.5)).any():continue\n   number+=1;review.append(dict(review_id=number,frame_id=fid,day=fit,class_name=r.class_name,source_confidence=float(r.confidence),teacher_confidence=float(conf[m][j]),agreement_iou=float(ovs[j]),roi=roi.tolist(),bbox=bb.tolist(),image_path=result.path,label_status='unreviewed_silver_candidate'))\n del model\npd.DataFrame(ledger).to_csv(P/'image_quality_ledger.csv',index=False);pd.DataFrame(allpred).to_csv(P/'teacher_predictions.csv',index=False)\n# At most two candidates from one frame and 30 per day; deterministic diversity selection.\nchosen=[]\nfor day in days:\n count={}\n for r in sorted([r for r in review if r['day']==day],key=lambda r:hashlib.sha256(str(r['review_id']).encode()).hexdigest()):\n  if count.get(r['frame_id'],0)>=2:continue\n  chosen.append(r);count[r['frame_id']]=count.get(r['frame_id'],0)+1\n  if sum(c['day']==day for c in chosen)>=30:break\n(P/'review_candidates.json').write_text(json.dumps(chosen,indent=2));(P/'all_eligible_candidates.json').write_text(json.dumps(review,indent=2))\nfor page in range((len(chosen)+11)//12):\n canvas=Image.new('RGB',(1200,960),'white');draw=ImageDraw.Draw(canvas)\n for k,r in enumerate(chosen[page*12:(page+1)*12]):\n  im=Image.open(r['image_path']).convert('RGB');sc=np.array([im.width/1280,im.height/720]*2);roi=np.array(r['roi']);native_roi=(roi*sc).astype(int);crop=im.crop(tuple(native_roi));factor=min(290/crop.width,270/crop.height);crop=crop.resize((max(1,int(crop.width*factor)),max(1,int(crop.height*factor))),Image.Resampling.NEAREST);x=(k%4)*300;y=(k//4)*320;canvas.paste(crop,(x,y+35));bx=(np.array(r['bbox'])-np.tile(roi[:2],2))*np.array([crop.width/(roi[2]-roi[0]),crop.height/(roi[3]-roi[1])]*2);draw.rectangle(tuple((bx+np.array([x,y+35,x,y+35])).astype(int)),outline='red',width=2);draw.text((x+4,y+4),f\"#{r['review_id']} {r['class_name']} {r['day'][-2:]}\",fill='black')\n canvas.save(P/f'review_page_{page:02d}.jpg',quality=95)\nprint('POOL_REVIEW_READY',len(review),'eligible',len(chosen),'selected',flush=True)\nprint('POOL_LABELS_NOT_USED_UNTIL_VISUAL_REVIEW',flush=True)\n")
Path('/kaggle/working/rascar_v14_pool_train_template.py.txt').write_text("\nfrom pathlib import Path\nimport os,sys,json,shutil,subprocess,time,hashlib\nimport numpy as np,pandas as pd,yaml,kagglehub\nfrom PIL import Image\nfrom sklearn.metrics import average_precision_score\nE=Path('/kaggle/working/rascar_v14');O=Path('/kaggle/working/oof_validation_v11');Y=E/'yolo26_clean';S=E/'stage5';S.mkdir(exist_ok=True);ds=S/'dataset';(ds/'images').mkdir(parents=True,exist_ok=True);(ds/'labels').mkdir(exist_ok=True)\n# Reviewed labels remain silver, distinct from official ground truth.\nAPPROVED_IDS=__APPROVED_IDS__\nREVIEW_DECISIONS=__REVIEW_DECISIONS__\nsource=S/'review_candidates_v6.json';download_output('shapodev/rascar-v14-geometry-quality-and-learned-ranking/versions/6','rascar_v14/stage6/pool/review_candidates.json',source)\nreview=json.loads(source.read_text());approved=[r for r in review if r['review_id'] in APPROVED_IDS];assert len(approved)==len(APPROVED_IDS);(S/'visual_review_decisions.json').write_text(json.dumps(REVIEW_DECISIONS,indent=2))\nfr=pd.read_csv(O/'train_frames.csv');fr['day']=pd.to_datetime(fr.timestamp,utc=True,format='mixed').dt.strftime('%Y-%m-%d');train=pd.read_csv(O/'train.csv');target=fr[fr.frame_id.isin(train.frame_id)];h=pd.read_csv(Y/'clean_training_boxes.csv');names=['cup','tray'];days=['2026-10-25','2026-10-26'];B=['cx','cy','w','h']\nfor r in target.itertuples():\n image=ds/'images'/r.image_path;shutil.copy2(Y/'dataset/images'/r.image_path,image);hh=h[h.frame_id.eq(r.frame_id)&h.class_name.isin(names)];lines=[str(names.index(x.class_name))+' '+' '.join(f'{getattr(x,c):.9f}' for c in B) for x in hh.itertuples()];(ds/'labels'/f'{r.frame_id}.txt').write_text('\\n'.join(lines)+'\\n' if lines else '')\nfor day in days:(ds/f'clean_{day}.txt').write_text('\\n'.join(str(ds/'images'/r.image_path) for r in target[target.day.eq(day)].itertuples())+'\\n')\nmf=pd.read_csv(E/'stage2/machine_frames.csv').set_index('frame_id');train_times=pd.to_datetime(fr.timestamp,utc=True,format='mixed').astype('int64').to_numpy();pool_paths={d:[] for d in days};ledger=[]\nfor r in approved:\n f=mf.loc[r['frame_id']];stamp=pd.Timestamp(f.timestamp);assert min(abs(train_times-stamp.value))/1e9>600;assert stamp.strftime('%Y-%m-%d')==r['day']\n path=Path(r['image_path']);assert path.is_file();im=Image.open(path).convert('RGB');sc=np.array([im.width/1280,im.height/720]*2);roi=(np.array(r['roi'])*sc).astype(int);crop=im.crop(tuple(roi));bb=np.array(r['bbox'])*sc-np.tile(roi[:2],2);bb[[0,2]]=np.clip(bb[[0,2]],0,crop.width);bb[[1,3]]=np.clip(bb[[1,3]],0,crop.height);xywh=np.r_[(bb[:2]+bb[2:])/2,bb[2:]-bb[:2]]/np.array([crop.width,crop.height]*2);assert (xywh>0).all() and (xywh<=1).all();stem=f\"silver_{r['day']}_{r['review_id']}\";dst=ds/'images'/f'{stem}.jpg';crop.save(dst,quality=98);(ds/'labels'/f'{stem}.txt').write_text(str(names.index(r['class_name']))+' '+' '.join(f'{v:.9f}' for v in xywh)+'\\n');pool_paths[r['day']].append(str(dst));ledger.append(dict(**r,training_crop=str(dst),silver=True,sha256=hashlib.sha256(Path(path).read_bytes()).hexdigest()))\nfor day in days:(ds/f'pool_{day}.txt').write_text('\\n'.join(pool_paths[day])+'\\n' if pool_paths[day] else '')\n(S/'accepted_silver_ledger.json').write_text(json.dumps(ledger,indent=2));print('POOL_DATASET',len(approved),{d:len(a) for d,a in pool_paths.items()},flush=True)\n(S/'train_specialist.py').write_text(__WORKER_SOURCE__)\n# Both clean and expanded variants use 80 fixed epochs and the same seed/config.\nfor fit in days+['all']:\n jobs={}\n for gpu,mode in enumerate(['clean','augmented']):\n  log=open(S/f'{mode}_{fit}.log','w');jobs[mode]=subprocess.Popen([sys.executable,'-u',str(S/'train_specialist.py'),mode,fit,str(gpu)],stdout=log,stderr=subprocess.STDOUT)\n while any(p.poll() is None for p in jobs.values()):\n  status={}\n  for mode,p in jobs.items():\n   f=S/f'{mode}_{fit}/train/results.csv'\n   try:epochs=len(pd.read_csv(f)) if f.exists() else 0\n   except pd.errors.EmptyDataError:epochs=0\n   status[mode]={'exit':p.poll(),'epochs':epochs}\n  print('SPECIALIST_PROGRESS',fit,json.dumps(status),flush=True);time.sleep(20)\n for mode,p in jobs.items():\n  print('SPECIALIST_DONE',fit,mode,p.returncode,flush=True)\n  if p.returncode:print((S/f'{mode}_{fit}.log').read_text()[-8000:]);raise RuntimeError('specialist failed; logs retained')\nsys.path.insert(0,str(Y));from frozen_scoring import score_refs_v4\nq=pd.read_csv(E/'stage1/oof/v8_baseline.csv');tr=pd.read_csv(O/'train.csv');qq=tr[tr.id.isin(q.id)].copy();test=pd.read_csv(O/'test.csv');bt=pd.read_csv('/kaggle/working/submission.csv').set_index('id').loc[test.id,'score'].to_numpy();metrics=[]\nfor mode in ['clean','augmented']:\n rr=pd.concat([pd.read_csv(S/f'{mode}_{day}/references.csv') for day in days],ignore_index=True);tt=pd.read_csv(S/f'{mode}_all/references.csv')\n for threshold in [.1,.25]:\n  raw=score_refs_v4(rr[rr.confidence.ge(threshold)],qq).set_index('id').loc[q.id,'score'].to_numpy();rawt=score_refs_v4(tt[tt.confidence.ge(threshold)],test).set_index('id').loc[test.id,'score'].to_numpy()\n  for weight in [.1,.2]:\n   pred=q.score.to_numpy().copy();mask=q.class_name.isin(names).to_numpy();pred[mask]=(1-weight)*pred[mask]+weight*raw[mask];pt=bt.copy();m=test.class_name.isin(names).to_numpy();pt[m]=(1-weight)*pt[m]+weight*rawt[m];name=f'pool_{mode}_conf{threshold}_w{weight}';dst=Path('/kaggle/working')/f'submission_{name}.csv';test[['id']].assign(score=pt).to_csv(dst,index=False);q.assign(score=pred).to_csv(S/f'{name}_oof.csv',index=False);row={'experiment':name,'pooled_ap':float(average_precision_score(q.error,pred)),'file':dst.name,'sha256':hashlib.sha256(dst.read_bytes()).hexdigest(),'public_lb':None}\n   for day,g in q.groupby('day'):row['day_'+day[-2:]]=float(average_precision_score(g.error,pred[g.index]))\n   for c,g in q.groupby('class_name'):row['ap_'+c]=float(average_precision_score(g.error,pred[g.index]))\n   metrics.append(row);print('POOL_RESULT',json.dumps(row),flush=True)\npd.DataFrame(metrics).to_csv(S/'pool_experiment_metrics.csv',index=False);print('POOL_EXPERIMENT_COMPLETE',flush=True)\n")
Path('/kaggle/working/rascar_v14_pool_train_worker.py').write_text("\nfrom pathlib import Path\nimport sys,os,json,time,hashlib\nos.environ['OMP_NUM_THREADS']='2';os.environ['WANDB_DISABLED']='true'\nimport numpy as np,pandas as pd,torch,yaml\nfrom ultralytics import YOLO,settings\nE=Path('/kaggle/working/rascar_v14');Y=E/'yolo26_clean';S=E/'stage5';ds=S/'dataset';mode,fit=sys.argv[1:3];gpu=int(sys.argv[3]);out=S/f'{mode}_{fit}';out.mkdir(exist_ok=True);torch.set_num_threads(2);settings.update({k:False for k in ['wandb','mlflow','comet','clearml','dvc','neptune'] if k in settings})\nfitdays=['2026-10-25','2026-10-26'] if fit=='all' else [fit];fitpaths=[]\nfor day in fitdays:\n fitpaths+=(ds/f'clean_{day}.txt').read_text().splitlines()\n if mode=='augmented':fitpaths+=(ds/f'pool_{day}.txt').read_text().splitlines()\nassert len(fitpaths)==len(set(fitpaths));lst=out/'train.txt';lst.write_text('\\n'.join(fitpaths)+'\\n');config={'path':str(ds),'train':str(lst),'val':str(lst),'names':{0:'cup',1:'tray'}};cfg=out/'data.yaml';cfg.write_text(yaml.safe_dump(config));(out/'training_manifest.json').write_text(json.dumps(dict(fitting_days=fitdays,training_images=fitpaths,epochs=80,seed=17,checkpoint='last epoch',pool_mode=mode,heldout_used_for_training_or_early_stopping=False),indent=2))\nmodel=YOLO(str(Y/'yolo26s.pt'));model.train(data=str(cfg),epochs=80,imgsz=1280,batch=4,device=gpu,workers=2,seed=17,deterministic=True,optimizer='AdamW',lr0=.0003,lrf=.1,weight_decay=.0005,warmup_epochs=3,patience=0,val=False,amp=True,cache=False,mosaic=.25,close_mosaic=10,mixup=0.0,scale=.25,translate=.05,fliplr=.5,flipud=0.,save=True,save_period=40,plots=False,project=str(out),name='train',exist_ok=False,verbose=False)\ncheckpoint=out/'train/weights/last.pt';hist=pd.read_csv(out/'train/results.csv');assert len(hist)==80;model=YOLO(str(checkpoint));assert list(model.names.values())==['cup','tray']\nif fit=='all':\n fr=pd.read_csv(E/'stage2/test_frames.csv');te=pd.read_csv('/kaggle/working/oof_validation_v11/test.csv');paths=[str(Y/'test_images'/r.image_path) for r in fr[fr.frame_id.isin(te.frame_id)].itertuples()]\nelse:\n held='2026-10-26' if fit.endswith('25') else '2026-10-25';paths=(ds/f'clean_{held}.txt').read_text().splitlines();assert set(paths).isdisjoint(fitpaths)\nrefs=[]\nfor result in model.predict(paths,imgsz=1280,batch=4,device=gpu,conf=.01,iou=.7,max_det=300,stream=True,verbose=False):\n fid=Path(result.path).stem;scale=np.array([1280/result.orig_shape[1],720/result.orig_shape[0]]*2)\n for j,(b,c,k) in enumerate(zip(result.boxes.xyxy.cpu().numpy(),result.boxes.conf.cpu().numpy(),result.boxes.cls.cpu().numpy())):refs.append(dict(frame_id=fid,class_name=model.names[int(k)],confidence=float(c),reference_id=f'{mode}_{fit}_{fid}_{j}',**dict(zip(['x1','y1','x2','y2'],b*scale))))\npd.DataFrame(refs,columns=['frame_id','class_name','confidence','reference_id','x1','y1','x2','y2']).to_csv(out/'references.csv',index=False);print('POOL_TRAIN_DONE',mode,fit,len(fitpaths),hashlib.sha256(checkpoint.read_bytes()).hexdigest(),flush=True)\n")
